const body = $input.first().json.body;
const data = body.data;

let lines = [`<b>📊 AlphaGPT Strategy [${data.index_code}]</b>`, ''];

for (const t of data.trades) {
  let indicator = '—';
  let retDisplay = '0.00%';
  if (t.return_pct > 0) {
    indicator = '▲';
    retDisplay = '+' + (t.return_pct * 100).toFixed(2) + '%';
  } else if (t.return_pct < 0) {
    indicator = '▼';
    retDisplay = (t.return_pct * 100).toFixed(2) + '%';
  }
  const posInfo = `Pos: ${t.position}`;
  const entryInfo = `Entry: ${t.entry_price}`;
  let exitInfo = `Hold Days: ${t.exit_offset || 'N/A'}`;
  if (t.exit_date !== 'N/A') {
    exitInfo = `Exit: ${t.exit_price} (${t.exit_date})`;
  }
  lines.push(`📅 ${t.date} ${posInfo} | Return: ${indicator} <b>${retDisplay}</b> ${entryInfo} | ${exitInfo}`);
}

lines.push('');
lines.push('<b>📈 Summary</b>');

const s = data.summary;
if (s) {
  lines.push(`  Investments: ${s.investment_count}`);
  lines.push(`  Profits: ${s.profit_count}`);
  lines.push(`  Win Rate: <b>${(s.win_rate * 100).toFixed(2)}%</b>`);
  lines.push(`  Simple Return: <b>${(s.simple_return * 100).toFixed(2)}%</b>`);
  lines.push(`  Compound Return: <b>${(s.compound_return * 100).toFixed(2)}%</b>`);
} else {
  lines.push('No active trades');
}

return [{ json: { message: lines.join('\n'), chatId: $env.TELEGRAM_CHAT_ID || '' } }];
